// --- Proposal events ---
const EnvelopeSchema = z.object({
    proposalId: nonEmpty(),
    schemaVersion: positiveInt(),
    baseRevision: nonNegativeInt(),
    cyclesPerProposal: positiveInt(),
    issuedAtCycle: nonNegativeInt(),
    references: z.array(z.string()),
});
export const ContentProposalSchema = EnvelopeSchema.extend({
    kind: z.literal('content'),
    payload: z.object({
        taskType: TaskTypeSchema,
        term: nonEmpty(),
        truth: TruthValueSchema.optional(),
    }),
});
export const RuleProposalSchema = EnvelopeSchema.extend({
    kind: z.literal('rule'),
    payload: z.object({
        ruleId: nonEmpty(),
        name: nonEmpty(),
        pattern: RulePatternSchema,
        truthFn: nonEmpty(),
        priority: unitInterval(),
        body: z.string().optional(),
        symbolicFallback: z.string().optional(),
    }),
});
export const ProposalSchema = z.discriminatedUnion('kind', [ContentProposalSchema, RuleProposalSchema]);
export const ProposalRejectedEventSchema = CognitiveEventBaseSchema.extend({
    type: z.literal('proposal.rejected'),
    engine: z.literal(PROPOSER_ORIGIN),
    payload: z.object({
        proposalId: z.string(),
        kind: z.enum(PROPOSAL_KINDS),
        reason: z.enum(PROPOSAL_REJECTIONS),
        detail: z.string(),
        observedRevision: nonNegativeInt(),
    }),
});
export const ProposalAdmittedEventSchema = CognitiveEventBaseSchema.extend({
    type: z.literal('proposal.admitted'),
    engine: z.literal(PROPOSER_ORIGIN),
    payload: z.object({
        proposalId: z.string(),
        kind: z.enum(PROPOSAL_KINDS),
        schemaVersion: positiveInt(),
        baseRevision: nonNegativeInt(),
        resultingRevision: positiveInt(),
        declaration: RuleDeclarationSchema.optional(),
        producer: z.string().optional(),
    }),
});
// --- Reasoning budget (before BudgetGate) ---
export const ConsumedBudgetSchema = z.object({
    cycles: nonNegativeInt().default(0),
    depth: nonNegativeInt().default(0),
    memoryOps: nonNegativeInt().default(0),
    llmCalls: nonNegativeInt().default(0),
});
export const TerminationReasonSchema = z.enum(TERMINATION_REASONS);
export const zeroConsumed = () => ({ cycles: 0, depth: 0, memoryOps: 0, llmCalls: 0 });
export const ReasoningBudgetSchema = z.object({
    maxCycles: positiveInt(),
    maxDepth: positiveInt(),
    maxMemoryOps: positiveInt(),
    maxLMCalls: nonNegativeInt(),
    wallclockDeadlineMs: positiveInt().optional(),
    abortSignal: z.unknown().optional(),
    terminationReason: TerminationReasonSchema.optional(),
    consumed: ConsumedBudgetSchema.default(zeroConsumed),
});
export const BudgetGateInputSchema = z.object({
    budget: ReasoningBudgetSchema.optional(),
    operation: BudgetOperationSchema,
    estimatedCost: positiveInt().optional(),
    scopeId: z.union([z.enum(BUDGET_SCOPE_IDS), z.string()]).optional(),
    correlationId: z.string().optional(),
});
export const BudgetGateOutputSchema = z.object({
    granted: z.boolean(),
    updatedBudget: ReasoningBudgetSchema.optional(),
    terminationReason: z.enum(TERMINATION_REASONS).optional(),
});
export const PerceptionGateOutputSchema = z.object({
    admitted: z.boolean(),
    task: TaskAdmittedEventSchema.shape.payload.optional(),
    rejectionReason: z.string().optional(),
});
// --- Union types and validators (at the end) ---
export const CognitiveEventSchema = z.discriminatedUnion('type', [
    TaskAdmittedEventSchema,
    DerivationAcceptedEventSchema,
    DerivationRecordEventSchema,
    BeliefRevisedEventSchema,
    ConceptActivatedEventSchema,
    BudgetExhaustedEventSchema,
    BudgetConsumedEventSchema,
    PolicyViolationEventSchema,
    AutonomyModeChangedEventSchema,
    SelfModProposalEventSchema,
    JudgmentResolvedEventSchema,
    GatePassedEventSchema,
    GateFailedEventSchema,
    EgressGateRejectedEventSchema,
    ShadowValidationDropEventSchema,
    ProposalSubmittedEventSchema,
    ProposalAdmittedEventSchema,
    ProposalRejectedEventSchema,
    SnapshotCreatedEventSchema,
    SnapshotRestoredEventSchema,
    ...NarEventSchemas,
]);
export const validateCognitiveEvent = (data) => CognitiveEventSchema.parse(data);
export const validateProposal = (data) => ProposalSchema.parse(data);
export const validateFormalizationCandidate = (data) => FormalizationCandidateSchema.parse(data);
export const validateFormalizationBatch = (data) => FormalizationBatchSchema.parse(data);
export const validateDerivationRecord = (data) => DerivationRecordSchema.parse(data);
export const validateReasoningBudget = (data) => ReasoningBudgetSchema.parse(data);
export const validateRuleTable = (data) => RuleTableSchema.parse(data);
const durableEventTypes = [
    "task.admitted", "derivation.accepted", "derivation.record", "belief.added",
    "belief.retracted", "belief.revised", "atom.derived", "atom.retracted",
    "goal.achieved", "goal.failed", "skill.executed", "tool.response",
    "conflict:detected", "budget.exhausted", "policy.violation", "autonomy.mode.changed",
    "egress.gate.rejected", "shadow.validation.dropped", "proposal.admitted",
    "proposal.rejected", "self-mod.proposal", "bootstrap"
];
export const DURABLE_EVENT_TYPES = new Set(durableEventTypes);
const recalledEventTypesArr = [
    "input.user", "belief.added", "belief.retracted", "belief.revised",
    "task.admitted", "derivation.accepted", "tool.request", "tool.response",
    "skill.executed", "goal.achieved", "goal.failed", "conflict:detected",
    "policy.violation", "budget.exhausted", "autonomy.mode.changed"
];
export const RECALLED_EVENT_TYPES = new Set(recalledEventTypesArr);
export const isDurableEvent = (event) => DURABLE_EVENT_TYPES.has(event.type);
export const recalledEventTypes = () => [...RECALLED_EVENT_TYPES];
const nonExecutingModes = new Set(["observe-only", "propose-only"]);
export const permitsExecution = (mode) => !nonExecutingModes.has(mode);
export const riskLevelOf = (risk) => ({ "low": "LOW", "medium": "MEDIUM", "high": "HIGH" }[risk]);
export const isNarEvent = (e) => e.engine === 'nar';
export const isEventType = (type) => (e) => e.type === type;
export const mintCognitiveEvent = (type, draft) => ({
    ...draft,
    type,
    timestamp: draft.timestamp ?? Date.now(),
    correlationId: draft.correlationId ?? generateId('corr'),
});
